targets.expr:
(
  label_replace(
    sum by(label_svc_dpu_nvidia_com_service) (
      kube_daemonset_status_desired_number_scheduled
        * on(daemonset, namespace) group_left(label_svc_dpu_nvidia_com_service)
          kube_daemonset_labels{label_svc_dpu_nvidia_com_service!=""}
      or
      kube_deployment_spec_replicas
        * on(deployment, namespace) group_left(label_svc_dpu_nvidia_com_service)
          kube_deployment_labels{label_svc_dpu_nvidia_com_service!=""}
    ),
    "service_id", "$1", "label_svc_dpu_nvidia_com_service", "(.*)"
  )
)
